type Entities<'a>=BTreeMap<i64,FloatRow<'a>>;
type Groups<'a>=BTreeMap<i64,Vec<FloatRow<'a>>>;
fn read_ground(value:&str)->Result<DeGroundCombo, ValueError>{match value{"A-R"=>Ok(DeGroundCombo::AR),"B-R"=>Ok(DeGroundCombo::BR),"C-R"=>Ok(DeGroundCombo::CR),"B-T"=>Ok(DeGroundCombo::BT),"C-T"=>Ok(DeGroundCombo::CT),"C-S"=>Ok(DeGroundCombo::CS),_=>Err(invalid("EN1998 unsupported ground combination"))}}
fn read_stiffness_basis(value:&str)->Result<StiffnessBasis, ValueError>{match value{"simplified"=>Ok(StiffnessBasis::Simplified),"declared"=>Ok(StiffnessBasis::Declared),_=>Err(invalid("EN1998 unsupported stiffness basis"))}}
fn read_member_kind(value:&str)->Result<MemberKind, ValueError>{match value{"beam"=>Ok(MemberKind::Beam),"column"=>Ok(MemberKind::Column),"wall"=>Ok(MemberKind::Wall),"brace"=>Ok(MemberKind::Brace),_=>Err(invalid("EN1998 unsupported member kind"))}}
fn boolean(row:FloatRow<'_>,column:usize)->Result<bool, ValueError>{match row.integer(column)?{0=>Ok(false),1=>Ok(true),_=>Err(invalid("EN1998 requires a boolean integer"))}}
fn ordinal(value:usize)->Result<Cell<'static>, ValueError>{Ok(Cell::Integer(i64::try_from(value).map_err(|error| invalid(error.to_string()))?))}
fn checkpoint(control:&mut SqliteSnapshotControl<'_>,position:usize,total:usize)->Result<(), ValueError>{if position%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,position,total)?;}Ok(())}
fn entities<'a>(database:&'a SqliteDatabase,table:&str,columns:usize,floats:&'static[FloatColumn],control:&mut SqliteSnapshotControl<'_>)->Result<Entities<'a>, ValueError>{let rows=&database.table(table)?.rows;let mut result=Entities::new();for(position,row)in rows.iter().enumerate(){checkpoint(control,position,rows.len())?;let row=FloatRow::new(row,floats)?;if row.values.len()!=columns||row.rowid<=0||row.integer(0)?!=row.rowid||result.insert(row.rowid,row).is_some(){return Err(invalid(format!("{table} requires exact fields and unique positive aliased identities")));}}Ok(result)}
fn groups<'a>(rows:&Entities<'a>,parents:&Entities<'a>,control:&mut SqliteSnapshotControl<'_>)->Result<Groups<'a>, ValueError>{let mut grouped:BTreeMap<i64,BTreeMap<usize,FloatRow<'a>>>=BTreeMap::new();for(position,row)in rows.values().copied().enumerate(){checkpoint(control,position,rows.len())?;let parent=row.integer(1)?;let ordinal=usize::try_from(row.integer(2)?).map_err(|error| invalid(error.to_string()))?;if !parents.contains_key(&parent)||grouped.entry(parent).or_default().insert(ordinal,row).is_some(){return Err(invalid("EN1998 foreign parent or duplicate ordinal"));}}let mut result=Groups::new();for(parent,siblings)in grouped{for(position,ordinal)in siblings.keys().copied().enumerate(){checkpoint(control,position,siblings.len())?;if position!=ordinal{return Err(invalid("EN1998 ordinals must be dense"));}}result.insert(parent,siblings.into_values().collect());}Ok(result)}
fn siblings<'a>(groups:&'a Groups<'a>,parent:i64)-> &'a[FloatRow<'a>]{groups.get(&parent).map(Vec::as_slice).unwrap_or_default()}
fn variables(out:&mut RowWriter<'_,'_>,table:&str,parent:i64,values:&[En1998VariableAction])->Result<(), ValueError>{for(position,value)in values.iter().enumerate(){out.insert_float(table,&[Cell::Integer(parent),ordinal(position)?,Cell::Text(&value.id),Cell::Text(imposed_category_text(value.category)),Cell::Real(value.qk_n)],VARIABLE)?;}Ok(())}
fn read_variables(rows:&[FloatRow<'_>],control:&mut SqliteSnapshotControl<'_>)->Result<Vec<En1998VariableAction>, ValueError>{let mut result=Vec::new();for row in rows{checkpoint(control,result.len(),rows.len())?;result.push(En1998VariableAction{id:reconstruct_text(control,row.text(3)?)?,category:read_imposed_category(row.text(4)?)?,qk_n:row.real(5)?});}Ok(result)}
fn analysis_method_choice_text(a:AnalysisMethodChoice)->&'static str{match a{AnalysisMethodChoice::Derived=>"derived",AnalysisMethodChoice::Lf=>"lf",AnalysisMethodChoice::Mrs=>"mrs",AnalysisMethodChoice::Pushover=>"pushover",AnalysisMethodChoice::Nlth=>"nlth",}}
fn read_analysis_method_choice(a:&str)->Result<AnalysisMethodChoice, ValueError>{match a{"derived"=>Ok(AnalysisMethodChoice::Derived),"lf"=>Ok(AnalysisMethodChoice::Lf),"mrs"=>Ok(AnalysisMethodChoice::Mrs),"pushover"=>Ok(AnalysisMethodChoice::Pushover),"nlth"=>Ok(AnalysisMethodChoice::Nlth),_=>Err(invalid("analysis method choice differs"))}}
fn bound_variables(bound:&mut NativeEncodingBound<'_,'_>,values:&[En1998VariableAction])->Result<(), ValueError>{for value in values{bound.add(16384)?;for text in [value.id.as_str(),imposed_category_text(value.category)]{bound.repeated(text.len(),24)?;}}Ok(())}

